WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_conc_sc_add'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '加纯溶质', 'kp-conc-sc-add', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "加纯溶质（加纯盐）"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心推论：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "加纯盐时，不仅盐变多了，盐水也变多了。纯盐可以看作浓度为 100% 的盐水！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“在 100克 20%的盐水中，加入 20克 纯盐，浓度变为多少？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破题"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "用十字交叉法时，把纯盐当成 100% 浓度的盐水进行交叉！"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忘记分母加盐：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果不用十字交叉，用常规公式算，很容易列成 (100*20% + 20) / 100。大错特错！盐加进去了，总重量也变重了，分母必须是 100 + 20。"}]}]}]}$$ AS jsonb), NULL, '加纯溶质的核心考点与实战推导。', category_node.id, CAST('["数量关系", "浓度问题", "加纯溶质"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_conc_sc_add", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
